OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 python -c 'import re, collections, warnings, numpy as np, pandas as pd; from sklearn.model_selection import GroupKFold; from sklearn.base import clone; from sklearn.ensemble import ExtraTreesRegressor, RandomForestRegressor; from sklearn.gaussian_process import GaussianProcessRegressor; from sklearn.gaussian_process.kernels import ConstantKernel, Matern, RBF, WhiteKernel; from sklearn.metrics import mean_absolute_error, root_mean_squared_error; warnings.filterwarnings("ignore"); d=pd.read_csv("b3_supercon_target.csv")
def parse(s):
    p=collections.defaultdict(float)
    for e,n in re.findall(r"([A-Z][a-z]?)([0-9]*\.?[0-9]*)",s): p[e]+=float(n) if n else 1.
    total=sum(p.values()); return {e:v/total for e,v in p.items()}
p=[parse(s) for s in d.composition]; elements=sorted(set().union(*p)); X=np.array([[v.get(e,0) for e in elements] for v in p]); mask=np.array([v.get("Cu",0)>0 and v.get("O",0)>.1 for v in p]); X=X[mask]; y=d.target.to_numpy()[mask]; groups=d.composition.to_numpy()[mask]; kernel=lambda base: ConstantKernel(1,(.01,100))*base+WhiteKernel(.1,(.001,2)); models={"GP-Matern":GaussianProcessRegressor(kernel=kernel(Matern(.15,(.01,2),nu=1.5)),normalize_y=True,n_restarts_optimizer=3,random_state=42),"GP-RBF":GaussianProcessRegressor(kernel=kernel(RBF(.15,(.01,2))),normalize_y=True,n_restarts_optimizer=3,random_state=42),"ExtraTrees":ExtraTreesRegressor(n_estimators=400,min_samples_leaf=1,max_features=1.,random_state=42,n_jobs=1),"RandomForest":RandomForestRegressor(n_estimators=400,min_samples_leaf=1,max_features=1.,random_state=42,n_jobs=1)}; candidates=["Y1Ba2Cu3O7","Bi2Sr2Ca1Cu2O8","Bi2Sr2Ca1Cu2O9","Bi2Sr2Ca1Cu2O10","Bi2Sr2Ca0.9Y0.1Cu2O10","Bi2Sr2Ca0.8Y0.2Cu2O10","Ba2Ca2Cu3O7","Ba2Ca2Cu3O8"]; cx=np.array([[v.get(e,0) for e in elements] for v in map(parse,candidates)]); out={"formula":candidates}
for name,model in models.items():
    pred=np.zeros(len(y))
    for train,test in GroupKFold(5,shuffle=True,random_state=42).split(X,y,groups):
        fit=clone(model).fit(X[train],y[train]); pred[test]=fit.predict(X[test])
    print(name,"CV MAE",round(mean_absolute_error(y,pred),2),"RMSE",round(root_mean_squared_error(y,pred),2),"high-Tc MAE",round(mean_absolute_error(y[y>=50],pred[y>=50]),2)); model.fit(X,y); out[name]=model.predict(cx)
    if hasattr(model,"kernel_"): print("kernel",model.kernel_); out[name+"-SD"]=model.predict(cx,return_std=True)[1]
print(pd.DataFrame(out).round(3).to_string(index=False))'

